-- 리눅스 세트 382. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_systemd_unit_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 382, 'systemd 서비스 직접 만들기: Restart, EnvironmentFile, drop-in, oneshot, timer, 의존, mask', '서비스 유닛을 직접 고치고 만들어 봅니다. 죽으면 다시 띄우는 Restart=, 환경변수 파일, 원본을 두고 덮어쓰는 드롭인과 systemctl cat, 한 번 실행하는 oneshot, 주기 실행 timer 와 list-timers, After 와 Requires 의 차이, 절대 못 켜게 하는 mask 를 익힙니다.', 'linux-systemd', '리눅스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 382);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 1, '죽으면 다시 살리기 (Restart=)', '**배경** — 서비스 프로세스가 죽었을 때 systemd 가 다시 띄울지는 유닛의 `Restart=` 가 정합니다. 기본값은 `no` 라서 죽으면 그대로 멈춥니다. `Restart=on-failure` 는 비정상 종료(오류 코드·시그널)일 때만 다시 띄우고, 다시 띄우기 전 기다리는 시간은 `RestartSec=` 입니다.

`/etc/systemd/system/flaky.service` 가 실행 중인데 `Restart=` 가 없습니다. **`[Service]` 에 `Restart=on-failure` 와 `RestartSec=1`** 을 넣고 systemd 가 다시 읽게 한 뒤 서비스를 **재시작** 하세요.', '유닛 파일을 고친 뒤에는 `systemctl daemon-reload` 로 다시 읽게 해야 합니다. 이미 떠 있는 서비스에는 `restart` 가 필요해요.', 'sed -i ''/^\\[Service\\]/a Restart=on-failure\\nRestartSec=1'' /etc/systemd/system/flaky.service
systemctl daemon-reload
systemctl restart flaky

# [Service] 에 Restart=on-failure·RestartSec=1 을 넣고 daemon-reload 후 restart. 죽이면 1 초 뒤 다시 뜬다', '["sh", "-c", "cat > /etc/systemd/system/flaky.service <<''EOF''\\n[Service]\\nExecStart=/bin/sleep 3600\\nEOF\\nsystemctl daemon-reload\\nsystemctl start flaky\\n"]', '["sh", "-c", "( [ \\"$(systemctl show -p Restart --value flaky)\\" = on-failure ] ) && ( [ \\"$(systemctl is-active flaky)\\" = active ] ) && ( p=$(systemctl show -p MainPID --value flaky); kill -9 $p; sleep 3; n=$(systemctl show -p MainPID --value flaky); [ \\"$n\\" != 0 ] && [ \\"$n\\" != \\"$p\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Restart 가 on-failure 로 읽혀 있다", "cmd": ["sh", "-c", "[ \\"$(systemctl show -p Restart --value flaky)\\" = on-failure ]"]}, {"label": "서비스가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(systemctl is-active flaky)\\" = active ]"]}, {"label": "프로세스를 강제로 죽이면 새 프로세스로 다시 뜬다", "cmd": ["sh", "-c", "p=$(systemctl show -p MainPID --value flaky); kill -9 $p; sleep 3; n=$(systemctl show -p MainPID --value flaky); [ \\"$n\\" != 0 ] && [ \\"$n\\" != \\"$p\\" ]"]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 2, '환경변수 파일 읽히기 (EnvironmentFile=)', '**배경** — 서비스에 설정값을 환경변수로 줄 때, 값을 유닛 파일에 직접 적지 않고 별도 파일로 두면 관리하기 좋습니다. 유닛의 `EnvironmentFile=파일` 이 `KEY=값` 줄들을 읽어 환경변수로 넣어 줍니다.

`/etc/systemd/system/envsvc.service` 는 `$GREETING` 을 `/tmp/greet.out` 에 적고 계속 돕니다. 환경변수 파일 `/etc/envsvc.env` (`GREETING=hello-etude`)는 있는데 유닛이 읽지 않아 `greet.out` 이 비어 있습니다. **유닛이 이 파일을 읽도록 고치고** 재시작해 `/tmp/greet.out` 에 `hello-etude` 가 나오게 하세요.', '`[Service]` 에 `EnvironmentFile=/etc/envsvc.env` 를 넣고, `daemon-reload` 후 `restart` 하세요.', 'sed -i ''/^\\[Service\\]/a EnvironmentFile=/etc/envsvc.env'' /etc/systemd/system/envsvc.service
systemctl daemon-reload
systemctl restart envsvc
sleep 1; cat /tmp/greet.out

# EnvironmentFile= 로 KEY=값 파일을 읽힌다. 서비스를 재시작해야 반영된다', '["sh", "-c", "rm -f /tmp/greet.out; echo GREETING=hello-etude > /etc/envsvc.env\\ncat > /etc/systemd/system/envsvc.service <<''EOF''\\n[Service]\\nExecStart=/bin/sh -c ''echo \\"$GREETING\\" > /tmp/greet.out; sleep 3600''\\nEOF\\nsystemctl daemon-reload\\nsystemctl start envsvc; sleep 1\\n"]', '["sh", "-c", "( systemctl show -p EnvironmentFiles --value envsvc | grep -q /etc/envsvc.env ) && ( grep -qx hello-etude /tmp/greet.out )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "유닛이 EnvironmentFile 로 읽도록 되어 있다", "cmd": ["sh", "-c", "systemctl show -p EnvironmentFiles --value envsvc | grep -q /etc/envsvc.env"]}, {"label": "greet.out 에 hello-etude 가 있다", "cmd": ["sh", "-c", "grep -qx hello-etude /tmp/greet.out"]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 3, '원본은 두고 덮어쓰기 (drop-in)', '**배경** — 패키지가 준 유닛 파일을 직접 고치면 업데이트 때 덮어써질 수 있습니다. 그래서 원본은 두고 **드롭인(drop-in)** 파일로 일부만 덮어씁니다. `유닛이름.service.d/아무이름.conf` 파일에 바꿀 항목만 `[Service]` 와 함께 적으면 됩니다.

`/etc/systemd/system/modesvc.service` 는 `MODE=dev` 로 돌며 `/tmp/mode.out` 에 `mode=...` 를 적습니다. **원본 파일은 건드리지 말고** 드롭인으로 `MODE=prod` 로 덮어쓴 뒤 재시작해, `/tmp/mode.out` 이 `mode=prod` 가 되게 하세요.', '디렉터리 `/etc/systemd/system/modesvc.service.d/` 를 만들고 `override.conf` 에 `[Service]` 와 `Environment=MODE=prod` 를 적으세요. 나중 값이 이깁니다.', 'mkdir -p /etc/systemd/system/modesvc.service.d
printf ''[Service]\\nEnvironment=MODE=prod\\n'' > /etc/systemd/system/modesvc.service.d/override.conf
systemctl daemon-reload
systemctl restart modesvc
sleep 1; cat /tmp/mode.out

# 원본은 그대로 두고 .service.d/override.conf 로 덮어쓴다. 같은 변수는 나중 값이 이긴다', '["sh", "-c", "rm -f /tmp/mode.out\\ncat > /etc/systemd/system/modesvc.service <<''EOF''\\n[Service]\\nEnvironment=MODE=dev\\nExecStart=/bin/sh -c ''echo mode=$MODE > /tmp/mode.out; sleep 3600''\\nEOF\\nsystemctl daemon-reload\\nsystemctl start modesvc; sleep 1\\n"]', '["sh", "-c", "( ls /etc/systemd/system/modesvc.service.d/*.conf >/dev/null 2>&1 ) && ( grep -q MODE=dev /etc/systemd/system/modesvc.service ) && ( [ \\"$(cat /tmp/mode.out)\\" = mode=prod ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "드롭인 파일이 있다", "cmd": ["sh", "-c", "ls /etc/systemd/system/modesvc.service.d/*.conf >/dev/null 2>&1"]}, {"label": "원본 유닛은 그대로 MODE=dev 다", "cmd": ["sh", "-c", "grep -q MODE=dev /etc/systemd/system/modesvc.service"]}, {"label": "mode.out 이 mode=prod 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/mode.out)\\" = mode=prod ]"]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 4, '덮어쓴 결과까지 합쳐 보기 (systemctl cat)', '**배경** — 드롭인이 있는 유닛은 원본 파일만 봐서는 실제 설정을 알 수 없습니다. `systemctl cat 유닛` 은 원본과 드롭인을 **파일 경로 주석과 함께 이어서** 보여 줍니다.

서비스 `catsvc` 에는 드롭인이 하나 있습니다. 원본과 드롭인 내용을 함께 보여 주는 출력을 **`/tmp/q4.txt`** 에 저장하세요.', '`cat` 이 아니라 `systemctl` 의 하위 명령이에요.', 'systemctl cat catsvc > /tmp/q4.txt
cat /tmp/q4.txt

# systemctl cat 은 원본과 .d 드롭인을 경로 주석(# /etc/...)과 함께 이어서 보여 준다', '["sh", "-c", "cat > /etc/systemd/system/catsvc.service <<''EOF''\\n[Service]\\nExecStart=/bin/sleep 3600\\nEOF\\nmkdir -p /etc/systemd/system/catsvc.service.d; printf \\"[Service]\\\\nEnvironment=FROM=dropin-marker\\\\n\\" > /etc/systemd/system/catsvc.service.d/10-extra.conf\\nsystemctl daemon-reload\\n"]', '["sh", "-c", "( grep -q \\"/etc/systemd/system/catsvc.service\\" /tmp/q4.txt ) && ( grep -q dropin-marker /tmp/q4.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "원본 파일 경로가 들어 있다", "cmd": ["sh", "-c", "grep -q \\"/etc/systemd/system/catsvc.service\\" /tmp/q4.txt"]}, {"label": "드롭인 내용이 들어 있다", "cmd": ["sh", "-c", "grep -q dropin-marker /tmp/q4.txt"]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 5, '한 번 실행하고 끝나는 서비스 (Type=oneshot)', '**배경** — 계속 떠 있는 데몬이 아니라 **한 번 실행하고 끝나는 작업**(백업, 정리)은 `Type=oneshot` 으로 만듭니다. systemd 는 명령이 끝날 때까지 기다리고, 끝나면 서비스는 inactive 로 돌아갑니다.

`/etc/systemd/system/stamp.service` 를 새로 만드세요. **`Type=oneshot`** 이고 `ExecStart` 는 `/bin/sh -c "date > /tmp/stamp.out"` 입니다. 만든 뒤 **한 번 실행** 해서 `/tmp/stamp.out` 이 생기게 하세요.', '`[Service]` 에 `Type=oneshot` 과 `ExecStart=` 를 쓰고 `daemon-reload` 한 뒤 `systemctl start stamp` 를 실행합니다.', 'cat > /etc/systemd/system/stamp.service <<''EOF''
[Service]
Type=oneshot
ExecStart=/bin/sh -c "date > /tmp/stamp.out"
EOF
systemctl daemon-reload
systemctl start stamp
cat /tmp/stamp.out

# oneshot 은 명령이 끝날 때까지 기다리고, 끝나면 inactive 가 된다', '["sh", "-c", "rm -f /tmp/stamp.out /etc/systemd/system/stamp.service; systemctl daemon-reload\\n"]', '["sh", "-c", "( [ \\"$(systemctl show -p Type --value stamp)\\" = oneshot ] ) && ( [ -s /tmp/stamp.out ] ) && ( [ \\"$(systemctl is-active stamp)\\" != active ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Type 이 oneshot 이다", "cmd": ["sh", "-c", "[ \\"$(systemctl show -p Type --value stamp)\\" = oneshot ]"]}, {"label": "stamp.out 이 만들어졌다", "cmd": ["sh", "-c", "[ -s /tmp/stamp.out ]"]}, {"label": "끝난 뒤 서비스는 active 가 아니다", "cmd": ["sh", "-c", "[ \\"$(systemctl is-active stamp)\\" != active ]"]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 6, '주기 실행 만들기 (timer)', '**배경** — cron 대신 systemd 로 주기 실행을 하려면 **타이머 유닛**을 씁니다. 이름이 같은 `.service` 를 `.timer` 가 시간에 맞춰 시작합니다. `OnCalendar=daily` 는 하루에 한 번이고, 타이머는 `[Install]` 에 `WantedBy=timers.target` 을 두고 `enable` 해야 부팅 뒤에도 돕니다.

`pulse.service` (한 번 실행하는 작업)가 이미 있습니다. 같은 이름의 **`pulse.timer`** 를 만들어 `OnCalendar=daily` 로 하루 한 번 돌게 하고, **부팅 시 자동 시작되게 enable 하면서 바로 시작** 하세요.', '`/etc/systemd/system/pulse.timer` 에 `[Timer]` 와 `[Install]` 을 쓰고, `systemctl enable --now pulse.timer` 를 하세요. 서비스가 아니라 **타이머** 를 enable 합니다.', 'cat > /etc/systemd/system/pulse.timer <<''EOF''
[Timer]
OnCalendar=daily

[Install]
WantedBy=timers.target
EOF
systemctl daemon-reload
systemctl enable --now pulse.timer

# .timer 는 같은 이름의 .service 를 시작한다. enable --now 로 부팅 자동 시작과 즉시 시작을 한 번에 한다', '["sh", "-c", "cat > /etc/systemd/system/pulse.service <<''EOF''\\n[Service]\\nType=oneshot\\nExecStart=/bin/true\\nEOF\\nrm -f /etc/systemd/system/pulse.timer\\nsystemctl daemon-reload\\n"]', '["sh", "-c", "( [ \\"$(systemctl is-enabled pulse.timer)\\" = enabled ] ) && ( [ \\"$(systemctl is-active pulse.timer)\\" = active ] ) && ( systemctl show -p TimersCalendar --value pulse.timer | grep -q \\"OnCalendar=\\\\*-\\\\*-\\\\* 00:00:00\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "타이머가 enabled 다", "cmd": ["sh", "-c", "[ \\"$(systemctl is-enabled pulse.timer)\\" = enabled ]"]}, {"label": "타이머가 active 다", "cmd": ["sh", "-c", "[ \\"$(systemctl is-active pulse.timer)\\" = active ]"]}, {"label": "매일 00:00 에 도는 달력 조건이다 (daily)", "cmd": ["sh", "-c", "systemctl show -p TimersCalendar --value pulse.timer | grep -q \\"OnCalendar=\\\\*-\\\\*-\\\\* 00:00:00\\""]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 7, '예약된 타이머 목록 보기 (list-timers)', '**배경** — 어떤 타이머가 있고 **다음에 언제 돌지** 는 `systemctl list-timers` 로 봅니다. 기본으로는 활성 타이머만 나옵니다.

타이머 `tick.timer` 가 활성 상태입니다. 예약된 타이머 목록을 **`/tmp/q7.txt`** 에 저장하세요.', '`systemctl list-timers` 를 쓰세요. 표가 길면 `--no-pager` 를 붙입니다.', 'systemctl list-timers --no-pager > /tmp/q7.txt
cat /tmp/q7.txt

# list-timers 는 NEXT(다음 실행), LAST(마지막 실행), UNIT(타이머), ACTIVATES(시작할 서비스)를 보여 준다', '["sh", "-c", "cat > /etc/systemd/system/tick.service <<''EOF''\\n[Service]\\nType=oneshot\\nExecStart=/bin/true\\nEOF\\ncat > /etc/systemd/system/tick.timer <<''EOF''\\n[Timer]\\nOnCalendar=daily\\n\\n[Install]\\nWantedBy=timers.target\\nEOF\\nsystemctl daemon-reload\\nsystemctl enable --now tick.timer\\n"]', '["sh", "-c", "( grep -q tick.timer /tmp/q7.txt ) && ( grep -q tick.service /tmp/q7.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q7.txt 에 tick.timer 가 있다", "cmd": ["sh", "-c", "grep -q tick.timer /tmp/q7.txt"]}, {"label": "시작할 서비스 tick.service 도 보인다", "cmd": ["sh", "-c", "grep -q tick.service /tmp/q7.txt"]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 8, '시작 순서와 의존 걸기 (After=, Requires=)', '**배경** — 서비스 A 가 서비스 B 를 필요로 하면 두 가지를 따로 적습니다. `Requires=B` 는 "A 를 시작하면 B 도 함께 시작하고, B 가 실패하면 A 도 멈춘다"는 **의존** 이고, `After=B` 는 "B 가 시작된 **뒤에** A 를 시작한다"는 **순서** 입니다. 둘은 별개라서 보통 함께 씁니다.

`/etc/systemd/system/web7.service` 가 `db7.service` 를 필요로 합니다. **`web7` 의 `[Unit]` 에 `Requires=db7.service` 와 `After=db7.service`** 를 넣고 systemd 가 다시 읽게 하세요.', '`[Unit]` 구역에 두 줄을 넣고 `daemon-reload` 하세요. `systemctl show -p After web7` 로 확인할 수 있어요.', 'sed -i ''/^\\[Unit\\]/a Requires=db7.service\\nAfter=db7.service'' /etc/systemd/system/web7.service
systemctl daemon-reload
systemctl show -p Requires -p After web7

# Requires= 는 함께 시작·실패 전파(의존), After= 는 시작 순서. 둘은 별개다', '["sh", "-c", "cat > /etc/systemd/system/db7.service <<''EOF''\\n[Service]\\nExecStart=/bin/sleep 3600\\nEOF\\ncat > /etc/systemd/system/web7.service <<''EOF''\\n[Unit]\\nDescription=web\\n\\n[Service]\\nExecStart=/bin/sleep 3600\\nEOF\\nsystemctl daemon-reload\\n"]', '["sh", "-c", "( systemctl show -p Requires --value web7 | grep -q db7.service ) && ( systemctl show -p After --value web7 | grep -q db7.service )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "web7 이 db7 을 Requires 한다", "cmd": ["sh", "-c", "systemctl show -p Requires --value web7 | grep -q db7.service"]}, {"label": "web7 이 db7 뒤에 시작된다 (After)", "cmd": ["sh", "-c", "systemctl show -p After --value web7 | grep -q db7.service"]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 9, '절대 시작되지 않게 막기 (mask)', '**배경** — `disable` 은 부팅 때 자동 시작만 끄고 `start` 로는 여전히 켤 수 있습니다. **`mask`** 는 유닛을 `/dev/null` 로 연결해 **어떤 방법으로도 시작할 수 없게** 막습니다. 사고 방지용으로 씁니다. 풀 때는 `unmask` 입니다.

패키지가 설치한 서비스 `pest.service` 가 있습니다. 이 서비스를 **mask** 해서 시작할 수 없게 하세요.', '`systemctl mask 유닛` 입니다. 확인은 `systemctl is-enabled pest` 에 `masked` 가 나오는지 보세요.', 'systemctl mask pest
systemctl is-enabled pest      # masked
systemctl start pest           # 실패

# mask 는 /etc/systemd/system/pest.service 를 /dev/null 로 잇는 심볼릭 링크로 만든다', '["sh", "-c", "cat > /usr/lib/systemd/system/pest.service <<''EOF''\\n[Service]\\nExecStart=/bin/sleep 3600\\nEOF\\nsystemctl unmask pest 2>/dev/null; rm -f /etc/systemd/system/pest.service\\nsystemctl daemon-reload\\n"]', '["sh", "-c", "( [ \\"$(systemctl is-enabled pest 2>&1)\\" = masked ] ) && ( ! systemctl start pest )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "pest 가 masked 다", "cmd": ["sh", "-c", "[ \\"$(systemctl is-enabled pest 2>&1)\\" = masked ]"]}, {"label": "시작하려 하면 실패한다", "cmd": ["sh", "-c", "! systemctl start pest"]}]', '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 10, 'Restart=on-failure 일 때 stop 하면?', '유닛에 `Restart=on-failure` 가 있습니다. 관리자가 `systemctl stop 서비스` 로 멈추면 systemd 는 이 서비스를 다시 띄울까요?', '문서의 Restart= 설명에 "systemd 작업의 결과로 죽은 경우"에 대한 문장이 있어요.', NULL, NULL, '[]', 'choice', '["실패가 아니므로 항상 다시 띄운다", "다시 띄우지 않는다 (systemd 작업으로 멈춘 것은 재시작 대상이 아니다)", "RestartSec 시간이 지나면 다시 띄운다", "`stop` 은 Restart 설정이 있으면 거부된다"]', 1, 'systemd.service 문서는 프로세스의 죽음이 systemd 작업(예: 서비스 `stop` 이나 `restart`)의 결과이면 서비스를 다시 띄우지 않는다고 설명합니다. `Restart=` 는 프로세스가 스스로 종료되거나 시그널로 죽거나 시간 초과가 난 경우에 적용됩니다.', NULL, NULL, NULL, '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 11, '유닛 파일을 고친 뒤', '유닛 파일을 고친 뒤 systemd 가 **변경된 유닛 파일을 다시 읽게** 하는 명령입니다. 빈칸을 채우세요.', 'daemon 이 들어가요.', NULL, NULL, '[]', 'fill', '["daemon-reload", "restart", "reload-config", "refresh"]', NULL, '`systemctl daemon-reload` 는 유닛 파일을 다시 읽어 systemd 의 설정을 갱신합니다. `restart` 는 서비스 프로세스를 다시 띄울 뿐 유닛 파일을 새로 읽지 않습니다. 파일을 고친 뒤에는 보통 `daemon-reload` 후에 `restart` 를 합니다.', '[0]', 'systemctl {0}', NULL, '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 382, 12, '서비스를 새로 만들어 돌리기', '유닛 파일을 직접 써서 서비스를 만들고 부팅 자동 시작까지 설정하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '쓰기 → 다시 읽기 → 켜기 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`/etc/systemd/system/` 에 `.service` 파일을 쓴다", "`systemctl daemon-reload` 로 다시 읽게 한다", "`systemctl enable --now` 로 자동 시작을 켜고 바로 시작한다", "`systemctl status` 로 active 인지 확인한다"]', NULL, '유닛 파일을 쓰고 `daemon-reload` 로 읽힌 뒤 `enable --now` 로 시작합니다. `status` 로 active (running) 를 확인하고 문제가 있으면 `journalctl -u 서비스` 로 로그를 봅니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "systemd.service 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html"}, {"title": "systemd.unit 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html"}, {"title": "systemd.timer 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"title": "systemctl 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"title": "systemd.exec 설명서", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.exec.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 382 AND order_index = 12);

